class PriorityFIFOResource:
    """Single/multi-capacity resource served by (priority, arrival) order.

    Priority is lower-is-first; requests with the same priority are served
    FIFO.  Mirrors simpy.Resource semantics (request() -> request.event).
    """

    def __init__(self, env, capacity, priority_order):
        self.env = env
        self.capacity = capacity
        self.priority_order = list(priority_order)
        self.request_queue = []
        self.busy = 0
        self._busy_event = env.Event()
        self._busy_event.succeed()

    def _rank(self, request):
        act = getattr(request, "activity", None)
        try:
            return self.priority_order.index(act)
        except ValueError:
            return len(self.priority_order)

    def request(self, activity=None):
        req = simpy.ResourceRequest(self, activity)
        self.env.process(self._admit(req))
        return req

    def _admit(self, req):
        self.request_queue.append(req)
        while True:
            self.request_queue.sort(key=lambda r: (self._rank(r), r.arrival))
            if self.busy < self.capacity and self.request_queue[0] is req:
                self.busy += 1
                self.request_queue.remove(req)
                req.event.succeed()
                return
            yield req.event

    def release(self, req=None):
        self.busy -= 1
        if self.busy <= 0:
            self._busy_event = self.env.Event()
            self._busy_event.succeed()

